import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] meetings = new long[(int) n][2];
        for (int i = 0; i < meetings.length; i++) {
            for (int j = 0; j < meetings[i].length; j++) {
                meetings[i][j] = Long.parseLong(next());
            }
        }

        int total = (int) n;
        long[] keys = new long[total];
        for (int i = 0; i < total; i++) keys[i] = (meetings[i][0] << 30) + meetings[i][1];
        Arrays.sort(keys);
        StringBuilder body = new StringBuilder();
        long count = 0;
        long end = keys[0] & ((1L << 30) - 1);
        for (int i = 1; i < total; i++) {
            long s = keys[i] >> 30;
            long e = keys[i] & ((1L << 30) - 1);
            if (s > end) {
                body.append(end).append(" ").append(s).append("\n");
                count++;
            }
            end = Math.max(end, e);
        }
        System.out.println(count);
        System.out.print(body);
    }
}
